class Solution:
    def shadowPairs(self, nums: list[int]) -> int:
        answer = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] < nums[j] and not any(nums[i] < nums[k] < nums[j] for k in range(i + 1, j)):
                    answer += 1
        return answer
